async function page(route,title,description,content,extra=''){routes.push(route);const file=route==='/'?'dist/index.html':`dist${route}index.html`;await mkdir(path.dirname(file),{recursive:true});await writeFile(file,shell(title,description,content,route,extra));}
async function copyAssetTree(source,destination){await mkdir(destination,{recursive:true});for(const entry of await readdir(source,{withFileTypes:true})){const from=path.join(source,entry.name),to=path.join(destination,entry.name);if(entry.isDirectory())await copyAssetTree(from,to);else await copyFile(from,to);}}
